import 'dart:convert';import 'package:flutter/material.dart';import 'package:flutter_test/flutter_test.dart';import 'package:http/http.dart' as http;import 'package:http/testing.dart';
import 'package:fluxidi_tracking/customer_booking/reliable_choice_api.dart';import 'package:fluxidi_tracking/company/reliable_dispatcher_panel.dart';import 'package:fluxidi_tracking/app_strings.dart';
void main(){testWidgets('P21 dispatcher exposes hard capabilities and deadline; no assignment without reliable shortlist',(tester)async{
 final client=MockClient((_)async=>http.Response(jsonEncode({'ok':true,'items':[{'tenant_id':'T','company_id':'C','booking_id':'B','reason':'no_reliable_candidates','pickup_summary':'Pickup','destination_summary':'Destination','deadline_at':DateTime.now().add(const Duration(minutes:1)).millisecondsSinceEpoch,'requirements':{'passengers':4,'luggage':3,'capabilities':['wheelchair','child_seat']},'candidates':[]}]}),200));var attempted=false;
 await tester.pumpWidget(MaterialApp(home:Scaffold(body:ReliableDispatcherPanelV1(api:ReliableChoiceApiV1(base:Uri.parse('https://local-fixture'),token:'company',client:client),tenant:'T',company:'C',language:AppLanguage.nl,selectAssignment:(_)async{attempted=true;return(vehicle:'V',driver:'D');}))));await tester.pumpAndSettle();
 expect(find.textContaining('rolstoel'),findsOneWidget);expect(find.textContaining('kinderzitje'),findsOneWidget);expect(find.textContaining('Bevestigen vóór'),findsOneWidget);expect(find.textContaining('Betrouwbare shortlist ontbreekt'),findsOneWidget);expect(tester.widget<TextButton>(find.byKey(const ValueKey('p20-assign-B'))).onPressed,isNull);expect(attempted,false);client.close();
});}
